method find_closest_elements(numbers: seq<real>) returns (first: real, second: real)
    requires |numbers| >= 2
    requires forall i, j :: 0 <= i < j < |numbers| ==> numbers[i] != numbers[j]
    ensures first <= second
    ensures exists i, j :: 0 <= i < j < |numbers| && abs(numbers[i] - numbers[j]) == abs(first - second)
{
